@Bean
@Primary
@ConfigurationProperties("spring.datasource.main")
public DataSource mainDataSource() {
    return DataSourceBuilder.create().build();
}

@Bean
@ConfigurationProperties("spring.datasource.sub")
public DataSource subDataSource() {
    return DataSourceBuilder.create().build();
}

@Bean
@Primary
public PlatformTransactionManager mainTxManager(DataSource mainDataSource) {
    return new DataSourceTransactionManager(mainDataSource);
}

@Bean
public PlatformTransactionManager subTxManager(DataSource subDataSource) {
    return new DataSourceTransactionManager(subDataSource);
}
